import * as THREE from 'three'
import type { OrbitControls } from 'three/examples/jsm/controls/OrbitControls'

import type {
  CameraManagerInterface,
  CameraState,
  CameraType,
  EventManagerInterface
} from './interfaces'

function resolveIncomingCustomUp(state: CameraState): THREE.Vector3 | null {
  if (state.useCustomUp === undefined) return null
  const storedUp = state.customUp
    ? new THREE.Vector3(state.customUp.x, state.customUp.y, state.customUp.z)
    : null
  if (storedUp && storedUp.lengthSq() > 0) return storedUp
  if (!state.useCustomUp || !state.quaternion) return null
  const q = new THREE.Quaternion(
    state.quaternion.x,
    state.quaternion.y,
    state.quaternion.z,
    state.quaternion.w
  )
  if (q.lengthSq() === 0) q.identity()
  return new THREE.Vector3(0, 1, 0).applyQuaternion(q)
}

export class CameraManager implements CameraManagerInterface {
  perspectiveCamera: THREE.PerspectiveCamera
  orthographicCamera: THREE.OrthographicCamera
  activeCamera: THREE.Camera

  private eventManager: EventManagerInterface

  private controls: OrbitControls | null = null

  private customUp: THREE.Vector3 | null = null
  private usingCustomUp = false

  DEFAULT_DISTANCE = 10
  DEFAULT_LOOK_AT = 0

  DEFAULT_CAMERA = {
    near: 0.01,
    far: 10000
  }

  DEFAULT_PERSPECTIVE_CAMERA = {
    fov: 35,
    aspect: 1
  }

  DEFAULT_FRUSTUM_SIZE = 10

  DEFAULT_ORTHOGRAPHIC_CAMERA = {
    left: -this.DEFAULT_FRUSTUM_SIZE / 2,
    right: this.DEFAULT_FRUSTUM_SIZE / 2,
    top: this.DEFAULT_FRUSTUM_SIZE / 2,
    bottom: -this.DEFAULT_FRUSTUM_SIZE / 2
  }

  constructor(
    _renderer: THREE.WebGLRenderer,
    eventManager: EventManagerInterface
  ) {
    this.eventManager = eventManager

    this.perspectiveCamera = new THREE.PerspectiveCamera(
      this.DEFAULT_PERSPECTIVE_CAMERA.fov,
      this.DEFAULT_PERSPECTIVE_CAMERA.aspect,
      this.DEFAULT_CAMERA.near,
      this.DEFAULT_CAMERA.far
    )

    this.orthographicCamera = new THREE.OrthographicCamera(
      this.DEFAULT_ORTHOGRAPHIC_CAMERA.left,
      this.DEFAULT_ORTHOGRAPHIC_CAMERA.right,
      this.DEFAULT_ORTHOGRAPHIC_CAMERA.top,
      this.DEFAULT_ORTHOGRAPHIC_CAMERA.bottom,
      this.DEFAULT_CAMERA.near,
      this.DEFAULT_CAMERA.far
    )

    this.reset()

    this.activeCamera = this.perspectiveCamera
  }

  init(): void {}

  dispose(): void {}

  setControls(controls: OrbitControls): void {
    this.controls = controls

    controls.addEventListener('end', () => {
      this.eventManager.emitEvent('cameraChanged', this.getCameraState())
    })
  }

  getCurrentCameraType(): CameraType {
    return this.activeCamera === this.perspectiveCamera
      ? 'perspective'
      : 'orthographic'
  }

  toggleCamera(cameraType?: CameraType): void {
    const oldCamera = this.activeCamera

    const position = oldCamera.position.clone()
    const rotation = oldCamera.rotation.clone()
    const up = oldCamera.up.clone()
    const target = this.controls?.target.clone() || new THREE.Vector3()

    const oldZoom =
      oldCamera instanceof THREE.OrthographicCamera
        ? oldCamera.zoom
        : (oldCamera as THREE.PerspectiveCamera).zoom

    if (!cameraType) {
      this.activeCamera =
        oldCamera === this.perspectiveCamera
          ? this.orthographicCamera
          : this.perspectiveCamera
    } else {
      this.activeCamera =
        cameraType === 'perspective'
          ? this.perspectiveCamera
          : this.orthographicCamera

      if (oldCamera === this.activeCamera) {
        return
      }
    }

    this.activeCamera.position.copy(position)
    this.activeCamera.rotation.copy(rotation)
    this.activeCamera.up.copy(up)

    if (this.activeCamera instanceof THREE.OrthographicCamera) {
      this.activeCamera.zoom = oldZoom
      this.activeCamera.updateProjectionMatrix()
    } else if (this.activeCamera instanceof THREE.PerspectiveCamera) {
      this.activeCamera.zoom = oldZoom
      this.activeCamera.updateProjectionMatrix()
    }

    if (this.controls) {
      this.controls.object = this.activeCamera
      this.controls.target.copy(target)
      this.controls.update()
    }

    this.eventManager.emitEvent('cameraTypeChange', cameraType)
  }

  setFOV(fov: number): void {
    if (this.activeCamera === this.perspectiveCamera) {
      this.perspectiveCamera.fov = fov
      this.perspectiveCamera.updateProjectionMatrix()
    }

    this.eventManager.emitEvent('fovChange', fov)
  }

  getCameraState(): CameraState {
    const { x, y, z, w } = this.activeCamera.quaternion
    const activeCamera = this.activeCamera as
      | THREE.PerspectiveCamera
      | THREE.OrthographicCamera
    return {
      position: this.activeCamera.position.clone(),
      target: this.controls?.target.clone() || new THREE.Vector3(),
      zoom:
        this.activeCamera instanceof THREE.OrthographicCamera
          ? this.activeCamera.zoom
          : (this.activeCamera as THREE.PerspectiveCamera).zoom,
      cameraType: this.getCurrentCameraType(),
      quaternion: { x, y, z, w },
      ...(this.customUp !== null && {
        useCustomUp: this.usingCustomUp,
        customUp: {
          x: this.customUp.x,
          y: this.customUp.y,
          z: this.customUp.z
        }
      }),
      fov: this.perspectiveCamera.fov,
      aspect: this.perspectiveCamera.aspect,
      near: activeCamera.near,
      far: activeCamera.far,
      frustum: {
        left: this.orthographicCamera.left,
        right: this.orthographicCamera.right,
        top: this.orthographicCamera.top,
        bottom: this.orthographicCamera.bottom
      }
    }
  }

  setCameraState(state: CameraState): void {
    if (state.cameraType !== this.getCurrentCameraType()) {
      this.toggleCamera(state.cameraType)
    }

    this.activeCamera.position.copy(state.position)

    this.controls?.target.copy(state.target)

    if (
      state.fov !== undefined &&
      this.activeCamera instanceof THREE.PerspectiveCamera
    ) {
      this.activeCamera.fov = state.fov
    }

    if (this.activeCamera instanceof THREE.OrthographicCamera) {
      this.activeCamera.zoom = state.zoom
      this.activeCamera.updateProjectionMatrix()
    } else if (this.activeCamera instanceof THREE.PerspectiveCamera) {
      this.activeCamera.zoom = state.zoom
      this.activeCamera.updateProjectionMatrix()
    }

    const incomingUp = resolveIncomingCustomUp(state)
    if (incomingUp) {
      this.customUp = incomingUp
      this.usingCustomUp = state.useCustomUp === true
      this.activeCamera.up.copy(
        this.usingCustomUp ? incomingUp : new THREE.Vector3(0, 1, 0)
      )
      this.eventManager.emitEvent('cameraUpStateChange', {
        hasCustomUp: true,
        usingCustomUp: this.usingCustomUp
      })
    } else if (this.customUp !== null) {
      this.customUp = null
      this.usingCustomUp = false
      this.activeCamera.up.set(0, 1, 0)
      this.eventManager.emitEvent('cameraUpStateChange', {
        hasCustomUp: false,
        usingCustomUp: false
      })
    }

    this.controls?.update()
  }

  setUseCustomUp(use: boolean): void {
    if (use && !this.customUp) return
    if (use === this.usingCustomUp) return
    const target =
      use && this.customUp ? this.customUp : new THREE.Vector3(0, 1, 0)
    this.activeCamera.up.copy(target)
    this.usingCustomUp = use
    this.controls?.update()
    this.eventManager.emitEvent('cameraUpStateChange', {
      hasCustomUp: this.customUp !== null,
      usingCustomUp: this.usingCustomUp
    })
  }

  handleResize(width: number, height: number): void {
    const aspect = width / height
    this.updateAspectRatio(aspect)
  }

  updateAspectRatio(aspect: number): void {
    if (this.activeCamera === this.perspectiveCamera) {
      this.perspectiveCamera.aspect = aspect
      this.perspectiveCamera.updateProjectionMatrix()
    } else {
      const frustumSize = 10
      this.orthographicCamera.left = (-frustumSize * aspect) / 2
      this.orthographicCamera.right = (frustumSize * aspect) / 2
      this.orthographicCamera.top = frustumSize / 2
      this.orthographicCamera.bottom = -frustumSize / 2
      this.orthographicCamera.updateProjectionMatrix()
    }
  }

  setupForModel(
    size: THREE.Vector3,
    center: THREE.Vector3 = new THREE.Vector3(0, size.y / 2, 0)
  ): void {
    const maxDim = Math.max(size.x, size.y, size.z)
    const distance = Math.max(size.x, size.z) * 2
    const height = center.y + maxDim

    this.perspectiveCamera.position.set(
      center.x + distance,
      height,
      center.z + distance
    )
    this.orthographicCamera.position.set(
      center.x + distance,
      height,
      center.z + distance
    )

    if (this.activeCamera === this.perspectiveCamera) {
      this.perspectiveCamera.lookAt(center)
      this.perspectiveCamera.updateProjectionMatrix()
    } else {
      const frustumSize = maxDim * 2
      const aspect = this.perspectiveCamera.aspect
      this.orthographicCamera.left = (-frustumSize * aspect) / 2
      this.orthographicCamera.right = (frustumSize * aspect) / 2
      this.orthographicCamera.top = frustumSize / 2
      this.orthographicCamera.bottom = -frustumSize / 2
      this.orthographicCamera.lookAt(center)
      this.orthographicCamera.updateProjectionMatrix()
    }

    this.controls?.target.copy(center)
    this.controls?.update()
  }

  reset(): void {
    this.perspectiveCamera.position.set(
      this.DEFAULT_DISTANCE,
      this.DEFAULT_DISTANCE,
      this.DEFAULT_DISTANCE
    )

    this.orthographicCamera.position.set(
      this.DEFAULT_DISTANCE,
      this.DEFAULT_DISTANCE,
      this.DEFAULT_DISTANCE
    )

    this.perspectiveCamera.lookAt(
      this.DEFAULT_LOOK_AT,
      this.DEFAULT_LOOK_AT,
      this.DEFAULT_LOOK_AT
    )
    this.orthographicCamera.lookAt(
      this.DEFAULT_LOOK_AT,
      this.DEFAULT_LOOK_AT,
      this.DEFAULT_LOOK_AT
    )

    this.perspectiveCamera.updateProjectionMatrix()
    this.orthographicCamera.updateProjectionMatrix()
  }
}
